\end{ex}

\begin{ex}%[9D3V3-5]
Biết hai số nguyên dương $x, y$ thỏa mãn $\dfrac{1}{x - 2} = \dfrac{5}{y - 10}$ và $xy = 80$. Giá trị của biểu thức $\dfrac{x\sqrt{x} - y\sqrt{y}}{x + \sqrt{xy} + y}$ ($x > 0, y > 0$) là (kết quả làm tròn đến hàng phần mười)
\shortans{-2,5}
\loigiai{
Từ $\dfrac{1}{x - 2} = \dfrac{5}{y - 10} \Rightarrow 1(y - 10) = 5(x - 2) \Rightarrow 1y - 10 = 5x - 10 \Rightarrow y = 5x$.\\
Thay vào $xy = 80$ ta được $5x^2 = 80 \Rightarrow x^2 = 16$. Do $x > 0$ nên $x = 4$, suy ra $y = 20$ (thỏa mãn ĐKXĐ).\\
Rút gọn hằng đẳng thức: $\dfrac{x\sqrt{x} - y\sqrt{y}}{x + \sqrt{xy} + y} = \sqrt{x} - \sqrt{y} = \sqrt{4} - \sqrt{20} \approx -2{,}5$.
}
\end{ex}

\begin{ex}%[9D3V3-5]
Biết hai số nguyên dương $x, y$ thỏa mãn $\dfrac{3}{x - 1} = \dfrac{9}{y - 3}$ và $xy = 147$. Giá trị của biểu thức $\dfrac{x\sqrt{x} - y\sqrt{y}}{x + \sqrt{xy} + y}$ ($x > 0, y > 0$) là (kết quả làm tròn đến hàng phần mười)
\shortans{-1,9}
\loigiai{
Từ $\dfrac{3}{x - 1} = \dfrac{9}{y - 3} \Rightarrow 3(y - 3) = 9(x - 1) \Rightarrow 3y - 9 = 9x - 9 \Rightarrow y = 3x$.\\
Thay vào $xy = 147$ ta được $3x^2 = 147 \Rightarrow x^2 = 49$. Do $x > 0$ nên $x = 7$, suy ra $y = 21$ (thỏa mãn ĐKXĐ).\\
Rút gọn hằng đẳng thức: $\dfrac{x\sqrt{x} - y\sqrt{y}}{x + \sqrt{xy} + y} = \sqrt{x} - \sqrt{y} = \sqrt{7} - \sqrt{21} \approx -1{,}9$.
}
\end{ex}

\begin{ex}%[9D3V3-5]
Biết hai số nguyên dương $x, y$ thỏa mãn $\dfrac{2}{x - 2} = \dfrac{8}{y - 8}$ và $xy = 36$. Giá trị của biểu thức $\dfrac{x\sqrt{x} - y\sqrt{y}}{x + \sqrt{xy} + y}$ ($x > 0, y > 0$) là (kết quả làm tròn đến hàng phần mười)
\shortans{-1,7}
\loigiai{
Từ $\dfrac{2}{x - 2} = \dfrac{8}{y - 8} \Rightarrow 2(y - 8) = 8(x - 2) \Rightarrow 2y - 16 = 8x - 16 \Rightarrow y = 4x$.\\
Thay vào $xy = 36$ ta được $4x^2 = 36 \Rightarrow x^2 = 9$. Do $x > 0$ nên $x = 3$, suy ra $y = 12$ (thỏa mãn ĐKXĐ).\\
Rút gọn hằng đẳng thức: $\dfrac{x\sqrt{x} - y\sqrt{y}}{x + \sqrt{xy} + y} = \sqrt{x} - \sqrt{y} = \sqrt{3} - \sqrt{12} \approx -1{,}7$.
}
\end{ex}
